let circuit=clone(templates[0].data),templateId='bridge',title='Wheatstone bridge',selected='R4',selectedWire=-1,tool='select',solution=null,samples=[],stale=true,undoStack=[],redoStack=[],wireStart=null,drag=null,view={x:0,y:0,w:840,h:576},lessonId='bridge',quantity='v',showVolts=true,toastTimer;
