function eng(v,u=''){if(Math.abs(v)<1e-12)v=0;const a=Math.abs(v);const scales=[[1e9,'G'],[1e6,'M'],[1e3,'k'],[1,''],[1e-3,'m'],[1e-6,'µ'],[1e-9,'n'],[1e-12,'p']];const [s,p]=a===0?[1,'']:scales.find(([s])=>a>=s)||[1e-12,'p'];return {value:Number((v/s).toPrecision(4)).toString(),unit:p+u};}
