function validateImport(s){const d=s.circuit;if(!d||!Array.isArray(d.components)||!Array.isArray(d.wires)||d.components.length>100||d.wires.length>300)throw Error('Expected a circuit export with at most 100 components and 300 wires.');const ids=new Set();for(const c of d.components){if(!componentTypes.some(t=>t.type===c.type)||typeof c.id!=='string'||c.id.length>32||ids.has(c.id)||![c.x,c.y].every(Number.isFinite)||(!c.unknown&&!Number.isFinite(c.value))||(c.length!==undefined&&(!Number.isFinite(c.length)||c.length<=0||c.length>500))||!Number.isFinite(c.rot)||Math.abs(c.x)>1e6||Math.abs(c.y)>1e6)throw Error('Invalid component data.');ids.add(c.id);}for(const w of d.wires){if(!Array.isArray(w.points)||w.points.length<2||w.points.length>100||!w.points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&Math.abs(p.x)<1e6&&Math.abs(p.y)<1e6))throw Error('Invalid wire data.');}return s;}
