$('#help').onclick=()=>modal('<h2>A workbench for your curiosity.</h2><ul><li><strong>Place:</strong> drag a component onto the grid, or click its palette button. Touch users can tap to add, then drag to position.</li><li><strong>Connect:</strong> click any terminal, then click its destination. Click a wire corner or junction to rename it in Properties; choose Draw wire from here to connect another wire. The editor returns to selection afterward. Choose Wire (W) to keep drawing wires. Wires default to 90° / 180° bends. Choose Direct or Custom angle in the toolbar, or select a wire to reroute it and drag its handles. Wire endpoints touching a segment form a junction; crossings alone do not.</li><li><strong>Edit:</strong> select a component. Resistance accepts 2k, 4k7, or 1M; arrows step by its smallest non-zero place. Other values use base units: F, H, V, A. For 10 µF, enter 0.00001. Use R to rotate by 90°, enter any angle in Properties, or Delete to remove. Mark missing values as unknown and open Homework for deterministic worked DC solutions. Moving components leaves wires in place.</li><li><strong>Simulate:</strong> include a source and ground. Choose DC, Transient, or AC, then Run (Enter). Select any component to measure it, or use Probe (P).</li><li><strong>Navigate:</strong> drag empty canvas space to pan, or scroll over empty space to zoom around the pointer. Both panes have independent cameras. Pan (H), the zoom buttons, middle-button dragging, and Ctrl + scroll also work. Ctrl + Z undoes, Ctrl + Shift + Z redoes. Escape cancels wiring.</li><li><strong>Breadboard:</strong> Inspect changes shared component values. Move parts drags legs to new holes. Wire joins free holes in one row or column; Erase wire removes jumpers. Edits update the schematic and simulation. Use Undo to reverse them.</li><li><strong>Keep your work:</strong> edits save locally. Export and Import let you keep several circuits or move them between devices.</li></ul><p>Ideal linear models only. DC capacitors are open; DC inductors are short. Transients start with zero stored energy. AC results use peak phasors at one frequency. Switches use 1 µΩ closed resistance and 1 TΩ open resistance. No semiconductor or thermal models.</p>');
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
window.addEventListener('keydown',e=>{if($('#modal').open)return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){wireStart=null;setTool('select');return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();persist();return;}if((e.ctrlKey||e.metaKey)||e.altKey)return;if(e.key==='/'){e.preventDefault();$('#component-search').focus();return;}if(!$('#workspace').classList.contains('active'))return;const k=e.key.toLowerCase();if(['v','w','p','h'].includes(k))setTool({v:'select',w:'wire',p:'probe',h:'pan'}[k]);if(k==='r')rotate();if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();removeSelected();}if(e.key==='Enter'){e.preventDefault();if(homeworkMode)homeworkUI?.work();else run();}});
breadboardUI=initBreadboard({getCircuit:()=>circuit,fmt,esc,onChange:plan=>{const next=circuitFromBreadboard(circuit,plan),changed=JSON.stringify(next.wires)!==JSON.stringify(circuit.wires);remember();circuit=next;selectedWire=-1;dirty();if(changed)requestAnimationFrame(fitCircuit);},onSelect:id=>{selected=id;focusInspector();renderProperties();}});
homeworkUI=initHomework({getCircuit:()=>circuit,fmt,esc,renderComponent:c=>componentSVG(c,false)});
$('#wire-routing').onchange=()=>{$('#wire-angle').hidden=$('#wire-routing').value!=='angle';};
$('#homework-example').onclick=()=>{loadTemplate('divider');const c=circuit.components.find(c=>c.id==='R2');c.unknown=true;dirty();showPage('homework');$('#hw-kind').value='unknown';$('#hw-component').value='R2';$('#hw-given-kind').value='voltage';$('#hw-given-part').value='R2';$('#hw-given-value').value='6';homeworkUI.refresh();};
renderPalette();renderLibrary();try{const raw=localStorage.getItem('circuit-builder-v1');if(raw){const saved=validateImport(JSON.parse(raw));circuit=saved.templateId==='bridge'?migrateLegacyBridge(saved.circuit):saved.circuit;title=String(saved.title||'My circuit').slice(0,80);templateId=saved.templateId;selected=circuit.components.find(c=>c.type==='resistor')?.id||null;$('#analysis').value=['dc','ac','transient'].includes(saved.mode)?saved.mode:'dc';$('#frequency').value=saved.frequency||100;$('#duration').value=saved.duration||.05;}}catch{/* A stale browser save should never prevent opening the lab. */}
modeFields();updateTitle();render();if(!circuit.components.some(c=>c.unknown))run();else $('#sim-status').textContent='Undefined values · solve in Homework';showPage(resolveRoute(location.hash),{updateUrl:false});if(templateId.startsWith('hw')){const t=templates.find(t=>t.id===templateId);if(t)homeworkUI.setQuery({...t.query||{kind:'loops'},description:t.description});}
window.addEventListener('hashchange',()=>showPage(resolveRoute(location.hash),{updateUrl:false}));
window.addEventListener('popstate',()=>showPage(resolveRoute(location.hash),{updateUrl:false}));

function dependentProperties(c){const terminals=circuit.components.flatMap(part=>pins(part).map((p,i)=>({value:part.id+':'+(i?'B':'A'),label:part.id+' · '+(i?'B':'A')})));const options=(items,value)=>'<option value="">Choose…</option>'+items.map(o=>`<option value="${esc(o.value)}" ${o.value===value?'selected':''}>${esc(o.label)}</option>`).join('');const law=({'vcvs':String.raw`v_o=\mu\left(v_+-v_-\right)`,'ccvs':String.raw`v_o=r_m i_c`,'vccs':String.raw`i_o=g_m\left(v_+-v_-\right)`,'cccs':String.raw`i_o=\beta i_c`})[c.type];return `<div class="control-fields"><div class="source-law">${mathHTML(law,{tex:true})}</div>${voltageControlled(c)?`<label class="field-label" for="control-positive">Sensing terminal (+)</label><select id="control-positive">${options(terminals,c.controlPositive)}</select><label class="field-label" for="control-negative">Sensing terminal (−)</label><select id="control-negative">${options(terminals,c.controlNegative)}</select>`:`<label class="field-label" for="control-branch">Controlling current · A → B</label><select id="control-branch">${options(circuit.components.filter(p=>p.type!=='ground'&&p.id!==c.id).map(p=>({value:p.id,label:p.id+' · '+p.type})),c.control)}</select>`}</div>`;}
function bandProperties(c){const code=resistorBands(c.value,{unknown:c.unknown,tolerance:c.tolerance||5});return `<div class="band-properties"><div class="band-preview" aria-label="${esc(code.bands.map(b=>b.name).join(', '))}">${code.bands.map(b=>`<span style="background:${b.color}" title="${b.name}"></span>`).join('')}</div><p>${code.valid?code.bands.map(b=>b.name).join(' · '):c.unknown?'Four bands appear when a value is known.':'Value is outside the four-band range.'}</p>${code.valid&&!code.exact?`<p class="band-approx">Bands encode ${esc(fmt(code.nominal,'Ω'))}; circuit uses ${esc(fmt(c.value,'Ω'))}.</p>`:''}<label class="field-label" for="resistor-tolerance">Band tolerance (visual)</label><select id="resistor-tolerance">${[1,2,5,10].map(v=>`<option value="${v}" ${v===(c.tolerance||5)?'selected':''}>±${v}%</option>`).join('')}</select></div>`;}
function bindExtraProperties(c){for(const [id,field]of [['control-positive','controlPositive'],['control-negative','controlNegative'],['control-branch','control'],['resistor-tolerance','tolerance']]){const input=$('#'+id);if(input)input.onchange=()=>{remember();c[field]=field==='tolerance'?Number(input.value):input.value;dirty();};}}
function fitCircuit(){const points=[...circuit.components.flatMap(pins),...circuit.wires.flatMap(w=>w.points)],ratio=$('#canvas').clientWidth/Math.max(1,$('#canvas').clientHeight)||840/576;if(!points.length){view={x:0,y:0,w:840,h:840/ratio};renderCanvas();return;}const minX=Math.min(...points.map(p=>p.x))-100,maxX=Math.max(...points.map(p=>p.x))+120,minY=Math.min(...points.map(p=>p.y))-75,maxY=Math.max(...points.map(p=>p.y))+90,w=Math.max(maxX-minX,(maxY-minY)*ratio,240),h=w/ratio;view={x:(minX+maxX-w)/2,y:(minY+maxY-h)/2,w,h};renderCanvas();}
function setDiagram(mode){diagramMode=mode;document.body.dataset.view=mode;document.body.classList.remove('controls-open');$('.canvas-wrap').classList.toggle('split-view',mode==='breadboard');$('#view-schematic').classList.toggle('active',mode==='schematic');$('#view-breadboard').classList.toggle('active',mode==='breadboard');renderCanvas();requestAnimationFrame(fitCircuit);}
$$('[data-category]').forEach(b=>b.onclick=()=>{paletteCategory=b.dataset.category;$('#component-search').value='';filterPalette();});
$$('[data-dock]').forEach(b=>b.onclick=()=>{dockPanel=b.dataset.dock;setDock();});
$('#toggle-controls').onclick=()=>document.body.classList.toggle('controls-open');$('#close-controls').onclick=()=>document.body.classList.remove('controls-open');
$('#quick-run').onclick=()=>homeworkMode?homeworkUI?.work():run();$('#view-schematic').onclick=()=>setDiagram('schematic');$('#view-breadboard').onclick=()=>setDiagram('breadboard');setDock();
let initialSize=true;new ResizeObserver(entries=>{const {width,height}=entries[0].contentRect;if(!width||!height)return;if(initialSize){initialSize=false;fitCircuit();}else{const cx=view.x+view.w/2,cy=view.y+view.h/2,ratio=width/height;if(ratio>view.w/view.h)view.w=view.h*ratio;else view.h=view.w/ratio;view.x=cx-view.w/2;view.y=cy-view.h/2;renderCanvas();}}).observe($('#canvas'));
document.addEventListener('show-board-wiring',e=>{const plan=e.detail,perPage=Math.max(3,Math.min(10,Math.floor((innerHeight*.75-180)/27))),parts=plan.ports;let page=0;const show=()=>{modal(`<h2>Breadboard wiring</h2><p>Each five-hole column is a bus on one side of the gap. External source modules retain their ideal circuit model.</p><table><thead><tr><th>Terminal</th><th>Net</th><th>Component hole</th><th>Bus hole</th></tr></thead><tbody>${parts.slice(page*perPage,(page+1)*perPage).map(p=>`<tr><td>${esc(p.component+'.'+p.pin)}</td><td>${p.node<0?'GND':'N'+(p.node+1)}</td><td>${p.hole.board+1}:${p.hole.row.toUpperCase()}${p.hole.column}</td><td>${p.hub.board+1}:${p.hub.row.toUpperCase()}${p.hub.column}</td></tr>`).join('')}</tbody></table><div class="modal-pager"><button id="wiring-prev" class="button" ${page===0?'disabled':''}>← Previous</button><span>${page+1} / ${Math.ceil(parts.length/perPage)}</span><button id="wiring-next" class="button" ${(page+1)*perPage>=parts.length?'disabled':''}>Next →</button></div>`);$('#wiring-prev').onclick=()=>{page--;show();};$('#wiring-next').onclick=()=>{page++;show();};};show();});

$('#library-prev').onclick=()=>{libraryPage--;renderLibrary();};$('#library-next').onclick=()=>{libraryPage++;renderLibrary();};$('#lesson-picker').onchange=e=>{lessonId=e.target.value;lessonStep=0;renderLesson();};

$('#toggle-chart').onclick=()=>{const panel=$('.results-panel');panel.dataset.resultTab=panel.dataset.resultTab==='chart'?'metrics':'chart';renderMeasurements();};


function mountPropertyTabs(c){const root=$('#properties'),type=root.querySelector('.property-type'),extra=root.querySelector('.control-fields,.band-properties'),placement=[root.querySelector('label[for="component-angle"]'),root.querySelector('.angle-input'),root.querySelector('.property-actions'),root.querySelector('.terminal-note')].filter(Boolean),value=document.createElement('div'),place=document.createElement('div'),tabs=document.createElement('div');if(propertySelection!==c.id){propertySection='value';propertySelection=c.id;}tabs.className='property-tabs';value.dataset.propertyPane='value';place.dataset.propertyPane='placement';for(const node of placement)place.append(node);if(extra){extra.remove();extra.dataset.propertyPane='extra';}for(const node of [...root.children])if(node!==type)value.append(node);root.append(tabs,value);if(extra)root.append(extra);root.append(place);const options=[['value','Value'],...(extra?[['extra',dependentTypes.includes(c.type)?'Control':'Bands']]:[]),['placement','Placement']];if(!options.some(([id])=>id===propertySection))propertySection='value';tabs.innerHTML=options.map(([id,label])=>'<button data-property-tab="'+id+'">'+label+'</button>').join('');const update=()=>{root.querySelectorAll('[data-property-pane]').forEach(p=>p.hidden=p.dataset.propertyPane!==propertySection);tabs.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.propertyTab===propertySection));};tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{propertySection=b.dataset.propertyTab;update();});update();}

let layoutFrame;window.addEventListener('resize',()=>{cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>renderLibrary());});

function beginDirectWire(p){setTool('wire');autoWire=true;wireStart={...p};$('#wire-hint').textContent='Click another terminal or grid point to connect · Esc cancels';$('#wire-hint').hidden=false;renderCanvas();}
function startPan(e){drag={type:'pan',start:point(e,false),view:{...view}};$('#canvas').dataset.dragging='true';$('#canvas').setPointerCapture(e.pointerId);}

window.addEventListener('beforeprint',()=>{const print=document.querySelector('#worked-solution .print-only');if(!print)return;print.querySelector('.pdf-breadboard')?.remove();breadboardUI?.render();const board=document.querySelector('#breadboard-canvas');if(board){const section=document.createElement('section');section.className='pdf-breadboard';section.innerHTML='<h2>Breadboard wiring</h2>';const svg=board.cloneNode(true);svg.removeAttribute('id');svg.style.cssText='width:100%;height:auto;max-height:450px';section.append(svg);print.append(section);}});
